node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Check the products table schema
const schema = db.prepare(\"PRAGMA table_info(products)\").all();
console.log('Products schema:', JSON.stringify(schema, null, 2));

// Search for the product
const product = db.prepare(\"SELECT * FROM products WHERE product_id = 'PROD-B98D14' OR product_id LIKE '%B98D14%'\").all();
console.log('Product:', JSON.stringify(product, null, 2));
"

